\begin{aligned}
    f(X = x \mid H = h, T= t) &= \frac{P(H=h, T=t \mid X=x) \cdot f(X=x)}{P(H=h, T=t)} &\quad \text { Bayes Theorem } \\
    &= \frac{\binom{h+t}{h} x^h (1-x)^t}{P(H=h, T=t)} &\quad \text { Binomial PMF, Uniform PDF } \\
    &= \frac{\binom{h+t}{h}}{P(H=h, T=t)} x^h (1-x)^t &\quad \text { Moving terms around } \\
    &= \frac{1}{c} \cdot x^h (1-x)^t &\quad \text { where }c = \int_0^1 x^h(1-x)^t dx \\
\end{aligned}

\begin{aligned}
    f(X = x) = \begin{cases} \frac{1}{B(a, b)} x^{a-1}(1-x)^{b-1} & \text { if } 0 < x <1 \\ 0 & \text { otherwise }\end{cases} &\quad\quad \text{where } B(a,b) = \int_0^1 x^{a-1}(1 - x)^{b - 1} dx
\end{aligned}

\begin{aligned}
    f(X = x \mid H = h, T=t) &= \frac{\P(H = h, T = t \mid X = x) f(X = x)}{\P(H = h, T = t)} &\quad \text{Bayes Theorem} \\
    &= \frac{\binom{h+t}{h} x^h (1-x)^t \cdot \frac{1}{c} \cdot x^{a-1} (1-x)^{b-1}}{\P(H = h, T = t)} &\quad \text{Binomial PMF, Beta PDF} \\
    &= K \cdot x^h (1 - x)^t \cdot x^{a-1} (1 - x)^{b-1} &\quad \text{Combine constants} \\
    &= K \cdot x^{a + h -1} (1 - x)^{b + t -1} &\quad \text{Combine like bases}
\end{aligned}
